INSERT INTO products (handle, title, price, compare_at_price, collection, images, colors, sizes, tags, description, in_stock) VALUES
('the-nova-joggers', 'The Nova Joggers', 6000.00, NULL, 'trousers', ARRAY['assets/DSC01528.jpg', 'assets/DSC01550.jpg', 'assets/DSC01522.jpg', 'assets/DSC01514.jpg'], '[{"label":"Vibrant Ankara","image":"assets/DSC01528.jpg","hex":"#422326"}]'::jsonb, ARRAY['S','M','L'], ARRAY['trousers','joggers'], 'Complete your look with The Nova Joggers—where vibrant African design meets unmatched comfort. Crafted from premium Ankara fabric, these joggers feature a soft black fleece waistband and fleece ankle cuffs for a warm, comfortable fit. The adjustable drawstring waist lets you customize the fit, while practical side pockets add everyday functionality. Designed for movement, warmth, and effortless style, The Nova Joggers are perfect for travel, relaxing, or stepping out in confidence.', true),
('the-nova-pullovers', 'The Nova Pullovers', 7000.00, NULL, 'tops', ARRAY['assets/DSC02582.jpg', 'assets/DSC02579.jpg', 'assets/DSC02554.jpg', 'assets/DSC02544.jpg'], '[{"label":"Ankara Black Fleece","image":"assets/DSC02582.jpg","hex":"#2A1719"}]'::jsonb, ARRAY['S','M','L'], ARRAY['tops','pullovers'], 'The Nova Pullover is designed for those who love bold African Fashion without compromising on comfort. It provides exceptional warmth while feeling gentle fabric along your skin. Whether you''re heading out on a chilly morning, travelling or relaxing, The Nova Pullover keeps you cozy and stylish all day long. Thoughtfully made for comfort, warmth and everyday elegance.', true),
('the-helsinki-blanket', 'The Helsinki Blanket', 8000.00, 10000.00, 'accessories', ARRAY['assets/DSC02687.jpg', 'assets/DSC02689.jpg', 'assets/DSC02676.jpg', 'assets/DSC02672.jpg'], '[{"label":"Kitenge Red/Black","image":"assets/DSC02687.jpg","hex":"#78281F"}]'::jsonb, ARRAY['M','L'], ARRAY['accessories','blankets'], 'Wrap yourself in warmth with The Helsinki Blanket where African craftsmanship meets everyday comfort. Made from vibrant kitenge fabric and lined with an ultra-soft fleece, this double-layered blanket is designed to keep you warm while adding a beautiful touch of African elegance to your home or wardrobe. Whether draped over your shoulders on a chilly evening, wrapped around you while travelling, or styled as a throw blanket on your sofa or bed, The Helsinki Blanket is as versatile as it is beautiful.', true),
('african-luxe-throw', 'African Luxe Throw', 8000.00, NULL, 'accessories', ARRAY['assets/DSC02676.jpg', 'assets/DSC02672.jpg', 'assets/DSC02662.jpg'], '[{"label":"Luxe Kitenge","image":"assets/DSC02676.jpg","hex":"#D4A843"}]'::jsonb, ARRAY['S','M','L'], ARRAY['accessories','throws'], 'Wrap yourself in warmth with the African Luxe Throw where African craftsmanship meets everyday comfort. Made from vibrant kitenge fabric and lined with an ultra-soft fleece, this double-layered throw is designed to keep you warm while adding a beautiful touch of African elegance to your home or wardrobe.', true),
('the-nova-hoodies', 'The Nova Hoodies', 7500.00, NULL, 'tops', ARRAY['assets/DSC01687.jpg', 'assets/DSC01655.jpg', 'assets/DSC01676.jpg', 'assets/DSC01669.jpg'], '[{"label":"Ankara Fleece Hood","image":"assets/DSC01687.jpg","hex":"#E59866"}]'::jsonb, ARRAY['S','M','L'], ARRAY['tops','hoodies'], 'Stay warm and stylish with this premium Ankara Hoodie, designed for everyday comfort and a bold, fashionable look. Made from high-quality Ankara fabric and finished with a soft fleece lining, it offers warmth, durability, and a comfortable fit. Perfect for casual wear, travel, and cooler weather.', true),
('the-diani-sunny-dress', 'The Diani Sunny Dress', 6000.00, NULL, 'dresses', ARRAY['assets/DSC01401.jpg', 'assets/DSC01383.jpg', 'assets/DSC01394.jpg', 'assets/DSC01389.jpg'], '[{"label":"Sunny Ankara","image":"assets/DSC01401.jpg","hex":"#D4A843"}]'::jsonb, ARRAY['S','M','L'], ARRAY['dresses'], 'The Diani Sunny Dress is designed to bring joy to every moment. Crafted from vibrant Ankara fabric, this lightweight dress features a flattering, flowing silhouette that moves beautifully with you. Whether you''re strolling by the beach, enjoying brunch with friends, exploring a new city, or celebrating a special occasion, The Diani Sunny Dress is made to help you feel confident, feminine, and effortlessly stylish. Easy to wear and beautifully handcrafted, it''s the perfect dress for sunshine-filled days and unforgettable moments.', true),
('the-talisman-kimono', 'The Talisman Kimono', 7000.00, NULL, 'tops', ARRAY['assets/DSC01755.jpg', 'assets/DSC01715.jpg', 'assets/DSC01736.jpg', 'assets/DSC01729.jpg'], '[{"label":"Flowing Ankara","image":"assets/DSC01755.jpg","hex":"#C97F5F"}]'::jsonb, ARRAY['M','L'], ARRAY['tops','kimonos'], 'The Talisman Kimono is a timeless layering piece designed to elevate every outfit with effortless elegance. Crafted from premium Ankara fabric, its flowing silhouette drapes beautifully, making it perfect for every season and every occasion. Whether worn over a dress, paired with jeans and shorts, or styled with your favorite everyday essentials, The Talisman Kimono adds a bold touch of African artistry to your wardrobe. Lightweight, versatile, and easy to style, it''s a statement piece you''ll reach for again and again.', true),
('noir-cape', 'Noir Cape', 8000.00, NULL, 'outerwear', ARRAY['assets/DSC02616.jpg', 'assets/DSC02608.jpg', 'assets/DSC02637.jpg'], '[{"label":"Fleece Kitenge Trim","image":"assets/DSC02616.jpg","hex":"#1C2833"}]'::jsonb, ARRAY['S','M','L'], ARRAY['outerwear','capes'], 'Wrap yourself in warmth, elegance, and effortless style. Crafted from ultra-soft, body-soothing black fleece and beautifully finished with vibrant kitenge detailing, the Noir Cape is designed for those who love comfort without compromising on style. Its flowing silhouette drapes beautifully over any outfit, making it the perfect layering piece for cool mornings, cozy evenings, travel, or everyday wear. The luxurious fleece provides exceptional warmth, while the bold kitenge trim adds a unique African touch. Designed to be unisex, the Noir Cape is timeless, versatile, and handcrafted to stand out.', true),
('village-market-palazzo', 'Village Market Palazzo', 6000.00, NULL, 'skirts', ARRAY['assets/DSC02056.jpg', 'assets/DSC02044.jpg', 'assets/DSC02035.jpg'], '[{"label":"Patchwork Ankara","image":"assets/DSC02056.jpg","hex":"#556B2F"}]'::jsonb, ARRAY['M','L'], ARRAY['skirts','trousers'], 'A statement piece designed for women who love bold style and effortless comfort. Crafted from two complementary Ankara prints, the Village Market Palazzo features a unique patchwork design that celebrates creativity and individuality. The flattering high waist, functional side pockets, and flowing wide-leg silhouette create a look that''s both comfortable and sophisticated. Perfect for brunch, shopping, travel, or making an everyday statement, each pair is handcrafted with attention to detail.', true),
('classic-dungarees', 'Classic Dungarees', 6500.00, NULL, 'trousers', ARRAY['assets/DSC02379.jpg', 'assets/DSC02369.jpg', 'assets/DSC02331.jpg'], '[{"label":"Classic Red/Blue","image":"assets/DSC02379.jpg","hex":"#CD6155"}]'::jsonb, ARRAY['M'], ARRAY['trousers','dungarees'], 'The Classic Dungarees combine modern style with everyday comfort. Designed with a relaxed fit and adjustable shoulder straps, they are perfect for casual outings, travel, or everyday wear. Available in multiple colours to suit different styles.', true)
ON CONFLICT (handle) DO UPDATE SET
